-- ========================================================


function IdolLive3D_GraphicSetting:__init()
    self.defaultGraphicQuality = XGraphicSetup.GetDefaultQuality() + 1 --索引从1开始
    self.globalGraphicConfig = self:GetGraphicQualityVoList()   -- 配表数据
end


-- 需手动调用 Delete()
function IdolLive3D_GraphicSetting:__delete()
    self:TurnOff()
end


function IdolLive3D_GraphicSetting:TurnOn()
    print("IdolLive3D_GraphicSetting TurnOn")

    if isNull(self.globalGraphicConfig) then 
        printError("数据异常 globalGraphicConfig")
        return
    end
    ---
    local highest = self.globalGraphicConfig[4] -- 超清模式

    self:SettingGraphicLevel( highest.graphicLevel ) --画质等级
    self:SettingGraphicResolution( highest.resolutionLevel ) --分辨率等级
    self:SettingGraphicFrame( highest.fpsLevel )  --fps等级
    self:SettingGraphicShadow( highest.shadowLevel ) --阴影等级
    self:SettingGraphicGlow( highest.bloomLevel ) --bloom等级
    self:SettingGraphicMaterial( highest.lodLevel )    --材质等级
    self:SettingGraphicAntialiasing( highest.fxaaLevel ) --抗锯齿等级
end


function IdolLive3D_GraphicSetting:TurnOff()
    print("IdolLive3D_GraphicSetting TurnOff")

    local _customGraphicSettingsData = self:GetCustomGraphicSettings() -- 全局数据

    if isNull(_customGraphicSettingsData) then 
        printError("数据异常 _customGraphicSettingsData")
        return
    end

    -- print( "graphicLevel = " .. tostring(_customGraphicSettingsData.graphicLevel) )
    -- print( "resolutionLevel = " .. tostring(_customGraphicSettingsData.resolutionLevel) )
    -- print( "fpsLevel = " .. tostring(_customGraphicSettingsData.fpsLevel) )
    -- print( "shadowLevel = " .. tostring(_customGraphicSettingsData.shadowLevel) )
    -- print( "bloomLevel = " .. tostring(_customGraphicSettingsData.bloomLevel) )
    -- print( "lodLevel = " .. tostring(_customGraphicSettingsData.lodLevel) )
    -- print( "fxaaLevel = " .. tostring(_customGraphicSettingsData.fxaaLevel) )

    self:SettingGraphicLevel( _customGraphicSettingsData.graphicLevel ) --画质等级
    self:SettingGraphicResolution( _customGraphicSettingsData.resolutionLevel ) --分辨率等级
    self:SettingGraphicFrame( _customGraphicSettingsData.fpsLevel ) --fps等级
    self:SettingGraphicShadow( _customGraphicSettingsData.shadowLevel ) --阴影等级
    self:SettingGraphicGlow( _customGraphicSettingsData.bloomLevel ) --bloom等级
    self:SettingGraphicMaterial( _customGraphicSettingsData.lodLevel ) --材质等级
    self:SettingGraphicAntialiasing( _customGraphicSettingsData.fxaaLevel ) --抗锯齿等级
end



-- ========================================================


function IdolLive3D_GraphicSetting:SettingGraphicLevel(index)
    XGraphicSetup.ApplyGraphic(index)
end


function IdolLive3D_GraphicSetting:SettingGraphicResolution(index)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting940, "ResolutionVo", index)
    XGraphicSetup.ApplyResolution(vo)
end


function IdolLive3D_GraphicSetting:SettingGraphicFrame(value)
    XGraphicSetup.ApplyFrameRate(value)
end


function IdolLive3D_GraphicSetting:SettingGraphicShadow(index)
    XGraphicSetup.ApplyShadow(index)
end

function IdolLive3D_GraphicSetting:SettingGraphicAntialiasing(index)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting942, "AntialiasingVo", index)
    XGraphicSetup.ApplyAntialias(vo)
end

function IdolLive3D_GraphicSetting:SettingGraphicGlow(index)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting941, "BloomVo", index)
    XGraphicSetup.ApplyBloom(vo)
end

function IdolLive3D_GraphicSetting:SettingGraphicMaterial(index)
    local lodTableFile = SettingModule.Get(SettingLODPath)
    local lodRow = lodTableFile:GetByPrimaryKey(checkNumber(index))
    local lod = checkNumber(lodRow:Get('lod'))
    XGraphicSetup.ApplyLOD(lod)
end


---获取本地存储的界面设置数据
function IdolLive3D_GraphicSetting:GetCustomGraphicSettings()
    local customGraphicSettings = PlayerPrefsUtility.GetEncryptedString(CUSTOM_SETTING_PREFS)
    local data
    if string.isEmpty(customGraphicSettings) then
        data = self.globalGraphicConfig[self.defaultGraphicQuality]
    else
        data = table.deserialize(customGraphicSettings)
    end
    return data
end



function IdolLive3D_GraphicSetting:GetGraphicQualityVoList()
    local settingMgr = SettingMgr:GetInstance()
    local tableFile = settingMgr:Get(AutoIds.IdSetting9)
    local GraphicQualityVo = import('Game.Setting.Vo.GraphicQualityVo')
    local graphicQualityVoList = {}
    for i, row in pairs(tableFile) do
        local vo = GraphicQualityVo.New()
        vo:FillVo(row)
        vo.Delete = nil
        vo.class = nil
        table.insert(graphicQualityVoList, vo)
    end
    return graphicQualityVoList
end





return IdolLive3D_GraphicSetting
